stmt-break-continue.code:
break                  // 跳出最内层循环
continue               // 进入最内层循环的下一次迭代
break outer            // 跳出标签为 outer 的循环
continue outer         // 进入标签为 outer 的循环的下一次迭代

outer: for (i in 0..10) {
    for (j in 0..10) {
        if (j == 3) { continue outer }
        if (i * j > 20) { break outer }
    }
}

