fn classify(n: i64) -> string {
    if (n < 0) { return "negative" }
    return match (n) {
        0 => "zero",
        1..=9 => "small",
        _ => "large",
    }
}

fn main() {
    for (i in [-1, 0, 5, 100]) {
        print(classify(i))
    }
}

